/// The ASCII folding of `c` under the default collation, if it has one.
#[inline]
pub(crate) fn fold_char(c: char) -> Option<&'static str> {
    let cp = c as u32;
    // Everything mapped lives in the Latin ranges; skip the search otherwise.
    if !(0xC0..0x250).contains(&cp) {
        return None;
    }
    FOLD.binary_search_by_key(&cp, |e| e.0)
        .ok()
        .map(|i| FOLD[i].1)
}
